48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.context.request.RequestContextHolder;
55	import org.springframework.web.context.request.ServletRequestAttributes;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Dedicated audit logger; a successful create emits one line here. */
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /** Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}. */
73	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
74	        new java.util.concurrent.atomic.AtomicLong();
75	
76	    /** Request header carrying the client-supplied key that makes a create idempotent. */
77	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
78	
79	    /**
80	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
81	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
82	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
83	     */
84	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
85	
86	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
87	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
88	
89	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
91	        "mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    private final ClinicService clinicService;
94	
95	    private final OwnerMapper ownerMapper;
96	
97	    private final PetMapper petMapper;
98	
99	    private final VisitMapper visitMapper;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper) {
105	        this.clinicService = clinicService;
106	        this.ownerMapper = ownerMapper;
107	        this.petMapper = petMapper;
108	        this.visitMapper = visitMapper;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        return withOwner(ownerId, owner ->
130	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
131	    }
132	
133	    /**
134	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
135	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
136	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
137	     */
138	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return onFound.apply(owner);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        String idempotencyKey = currentIdempotencyKey();
150	        if (idempotencyKey != null) {
151	            Integer existingId = idempotentCreates.get(idempotencyKey);
152	            if (existingId != null) {
153	                Owner existing = this.clinicService.findOwnerById(existingId);
154	                if (existing != null) {
155	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
156	                }
157	            }
158	        }
159	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
160	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
161	                && response.getBody() != null && response.getBody().getId() != null) {
162	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
163	        }
164	        return response;
165	    }
166	
167	    /**
168	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
169	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
170	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
171	     */
172	    private static String currentIdempotencyKey() {
173	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
174	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
175	            if (key != null && !key.isBlank()) {
176	                return key;
177	            }
178	        }
179	        return null;
180	    }
181	
182	    /**
183	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
184	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
185	     * identity and per-city gates are applied, the derived registration attributes are
186	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
187	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
188	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
189	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
190	     * of the create pipeline.
191	     */
192	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
193	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
194	        if (!normalizeAndValidateFields(owner)) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
198	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
199	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
200	        }
201	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
202	        owner.setRegistrationDate(registrationDate);
203	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
204	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
205	        }
206	        owner.setHouseholdId(householdId(owner));
207	        owner.setIdentityKey(identityKey(owner));
208	        if (isDuplicate(owner)) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
212	        if (countOwnersInCity(owner.getCity()) >= 50) {
213	            return new ResponseEntity<>(HttpStatus.CONFLICT);
214	        }
215	        assignRegistrationAttributes(owner, sharesHousehold);
216	        this.clinicService.saveOwner(owner);
217	        auditOwnerCreated(owner);
218	        HttpHeaders headers = new HttpHeaders();
219	        headers.setLocation(UriComponentsBuilder.newInstance()
220	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
221	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
222	    }
223	
224	    /**
225	     * Emit the audit trail for a freshly persisted {@code owner} on the dedicated {@code AUDIT}
226	     * logger: the human-readable line followed by the structured {@link OwnerCreatedEvent}. This is
227	     * the one place a created owner's identifiers are read for the audit trail, so a change to which
228	     * identifier is audited is confined here rather than woven through the create pipeline.
229	     */
230	    private void auditOwnerCreated(Owner owner) {
231	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
232	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
233	        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
234	    }
235	
236	    /**
237	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
238	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
239	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
240	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
241	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
242	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
243	     */
244	    private boolean normalizeAndValidateFields(Owner owner) {
245	        if (!normalizeAddressFields(owner)) {
246	            return false;
247	        }
248	        if (owner.getEmail() != null) {
249	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
250	            if (!EMAIL_PATTERN.matcher(email).matches()) {
251	                return false;
252	            }
253	            if (isDisposableEmailDomain(email)) {
254	                return false;
255	            }
256	            owner.setEmail(email);
257	        }
258	        if (!isPostcodeValidForCity(owner)) {
259	            return false;
260	        }
261	        String telephone = normalizeTelephone(owner.getTelephone());
262	        if (telephone == null) {
263	            return false;
264	        }
265	        owner.setTelephone(telephone);
266	        return true;
267	    }
268	
269	    /**
270	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
271	     * returning whether the owner may proceed to creation. The structured fields are preferred when
272	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
273	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
274	     * composed value (the normalized addressLine1, with a single space and the normalized
275	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
276	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
277	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
278	     * address. This is the single place the owner's address is read, canonicalized and written back,
279	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
280	     */
281	    private boolean normalizeAddressFields(Owner owner) {
282	        String line1 = normalizeAddress(owner.getAddressLine1());
283	        if (!line1.isEmpty()) {
284	            String line2 = normalizeAddress(owner.getAddressLine2());
285	            owner.setAddressLine1(line1);
286	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
287	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
288	            return true;
289	        }
290	        String address = normalizeAddress(owner.getAddress());
291	        if (address.isEmpty()) {
292	            return false;
293	        }
294	        owner.setAddress(address);
295	        return true;
296	    }
297	
298	    /**
299	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
300	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
301	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
302	     */
303	    private static boolean isDisposableEmailDomain(String email) {
304	        int at = email.lastIndexOf('@');
305	        if (at < 0) {
306	            return false;
307	        }
308	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
309	    }
310	
311	    /**
312	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
313	     * computed against the owner population rather than carried on the owner itself (currently the
314	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
315	     * listing intentionally omits these flags.
316	     */
317	    private OwnerDto buildOwnerDto(Owner owner) {
318	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
319	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
320	        ownerDto.setCapacityWarning(isCapacityWarning(owner));
321	        return ownerDto;
322	    }
323	
324	    /**
325	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
326	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
327	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
328	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
329	     * owners already present, before the new one is added).
330	     */
331	    private boolean isCapacityWarning(Owner owner) {
332	        long othersInCity = countOtherOwnersInCity(owner);
333	        return othersInCity >= 40 && othersInCity < 50;
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Override
338	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
339	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
340	        if (currentOwner == null) {
341	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	        }
343	        currentOwner.setAddress(ownerFieldsDto.getAddress());
344	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
345	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
346	        currentOwner.setCity(ownerFieldsDto.getCity());
347	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
348	        currentOwner.setLastName(ownerFieldsDto.getLastName());
349	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
350	        String email = ownerFieldsDto.getEmail();
351	        if (email != null) {
352	            email = email.trim().toLowerCase(Locale.ROOT);
353	            if (!EMAIL_PATTERN.matcher(email).matches()) {
354	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
355	            }
356	        }
357	        currentOwner.setEmail(email);
358	        this.clinicService.saveOwner(currentOwner);
359	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
360	    }
361	
362	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
363	    @Transactional
364	    @Override
365	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
366	        return withOwner(ownerId, owner -> {
367	            owner.setDeleted(true);
368	            this.clinicService.saveOwner(owner);
