437	
438	    /** Matches a well-formed postcode: exactly 4 digits. */
439	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
440	
441	    /**
442	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
443	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
444	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
445	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
446	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
447	     */
448	    private static boolean isPostcodeValidForCity(Owner owner) {
449	        String postcode = owner.getPostcode();
450	        if (postcode == null) {
451	            return true;
452	        }
453	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
454	            return false;
455	        }
456	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
457	        if (range == null) {
458	            return true;
459	        }
460	        int value = Integer.parseInt(postcode);
461	        return value >= range[0] && value <= range[1];
462	    }
463	
464	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
465	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
466	
467	    /**
468	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
469	     * code are kept when present; otherwise country code '+61' is assumed and a single
470	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
471	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
472	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
473	     * Returns {@code null} when the number cannot form a valid E.164 value.
474	     */
475	    private static String normalizeTelephone(String telephone) {
476	        if (telephone == null) {
477	            return null;
478	        }
479	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
480	        String e164;
481	        if (cleaned.startsWith("+")) {
482	            e164 = cleaned;
483	        } else {
484	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
485	            e164 = "+61" + national;
486	        }
487	        if (!E164_PATTERN.matcher(e164).matches()) {
488	            return null;
489	        }
490	        return hasValidNationalNumberLength(e164) ? e164 : null;
491	    }
492	
493	    /**
494	     * Whether the national number of a well-formed E.164 value has the length required for its
495	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
496	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
497	     */
498	    private static boolean hasValidNationalNumberLength(String e164) {
499	        String countryCode = Owner.countryCodeOf(e164);
500	        if (countryCode == null) {
501	            return true;
502	        }
503	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
504	    }
505	
506	    /**
507	     * Compute and assign the derived attributes carried by a newly registered owner: the member id,
508	     * household id, namesake count and household member count. Each is derived from the owner's
509	     * already-normalized fields and the existing owner population, so this must run before the owner
510	     * is saved, while the counts still exclude the owner being created.
511	     *
512	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
513	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
514	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
515	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
516	     */
517	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
518	        owner.setMemberId(generateMemberId(owner));
519	        owner.setHouseholdId(householdId(owner));
520	        owner.setNamesakeCount(countNamesakes(owner));
521	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
522	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
523	        if (declaredMember) {
524	            owner.setPossibleDuplicate(false);
525	            owner.setPossibleDuplicateOf(null);
526	        } else {
527	            assignPossibleDuplicate(owner);
528	        }
529	    }
530	
531	    /**
532	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
533	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
534	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
535	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
536	     * matching owner's id. Runs before save, against the existing owner population.
537	     */
538	    private void assignPossibleDuplicate(Owner owner) {
539	        Integer matchId = findPossibleDuplicateOf(owner);
540	        owner.setPossibleDuplicate(matchId != null);
541	        owner.setPossibleDuplicateOf(matchId);
542	    }
543	
544	    /**
545	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
546	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
547	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
548	     * with the same last name and postcode but different telephones differ in key and so match here,
549	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
550	     * the lowest id is returned. An owner without a postcode never matches.
551	     */
552	    private Integer findPossibleDuplicateOf(Owner owner) {
553	        String postcode = owner.getPostcode();
554	        if (postcode == null) {
555	            return null;
556	        }
557	        String soundex = soundex(owner.getLastName());
558	        String identityKey = owner.getIdentityKey();
559	        return this.clinicService.findAllOwners().stream()
560	            .filter(existing -> !existing.isDeleted())
561	            .filter(existing -> existing.getId() != null
562	                && postcode.equals(existing.getPostcode())
563	                && soundex(existing.getLastName()).equals(soundex)
564	                && !identityKey.equals(existing.getIdentityKey()))
565	            .map(Owner::getId)
566	            .min(Integer::compareTo)
567	            .orElse(null);
568	    }
569	
570	    /**
571	     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code derived
572	     * from the owner's postcode ({@link Owner#getRegion()}), FY the two-digit
573	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
574	     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
575	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
576	     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
577	     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
578	     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
579	     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
580	     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
581	     */
582	    private String generateMemberId(Owner owner) {
583	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
584	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
585	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
586	        String core = owner.getRegion() + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
587	        String base = core + Owner.luhnCheckDigit(core);
588	        return deduplicateMemberId(base);
589	    }
590	
591	    /**
592	     * De-duplicate a computed member id against the existing owner population: when {@code base}
593	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
594	     * {@code n} of 2 or more that yields an id no existing owner carries.
595	     */
596	    private String deduplicateMemberId(String base) {
597	        Set<String> existing = this.clinicService.findAllOwners().stream()
598	            .map(Owner::getMemberId)
599	            .filter(code -> code != null)
600	            .collect(java.util.stream.Collectors.toSet());
601	        if (!existing.contains(base)) {
602	            return base;
603	        }
604	        int n = 2;
605	        while (existing.contains(base + "-" + n)) {
606	            n++;
607	        }
608	        return base + "-" + n;
609	    }
610	
611	    /**
612	     * The number of existing owners registered in {@code city}, compared case-insensitively
613	     * with collapsed whitespace.
614	     */
615	    private int countOwnersInCity(String city) {
616	        String normalized = normalizeHouseholdField(city);
617	        return (int) this.clinicService.findAllOwners().stream()
618	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
619	            .count();
620	    }
621	
622	    /**
623	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
624	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
625	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
626	     */
627	    private long countOtherOwnersInCity(Owner owner) {
628	        String normalized = normalizeHouseholdField(owner.getCity());
629	        return this.clinicService.findAllOwners().stream()
630	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
631	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
632	            .count();
633	    }
634	
635	    /**
636	     * The effective registration date to store for a new owner: the date supplied on the request
637	     * when present, otherwise the current server date, in either case rolled forward to a business
638	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
639	     * This single point of resolution is what every registration-date-derived value (the stored
640	     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
641	     */
642	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
643	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
644	        return toBusinessDay(date);
645	    }
646	
647	    /**
648	     * The fixed list of public holidays that a registration date must not fall on. A date landing
649	     * on one of these is rolled forward, exactly as weekends are.
650	     */
651	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
652	        LocalDate.of(2026, 1, 1),
653	        LocalDate.of(2026, 1, 26),
654	        LocalDate.of(2026, 4, 25),
655	        LocalDate.of(2026, 12, 25),
656	        LocalDate.of(2026, 12, 28));
657	
658	    /**
659	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
660	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
661	     * unchanged.
662	     */
663	    private static LocalDate toBusinessDay(LocalDate date) {
664	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
665	                || PUBLIC_HOLIDAYS.contains(date)) {
666	            date = date.plusDays(1);
667	        }
668	        return date;
669	    }
670	
671	    /**
672	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
673	     * last name, compared case-insensitively.
674	     */
675	    private int countNamesakes(Owner owner) {
676	        String firstName = normalizeHouseholdField(owner.getFirstName());
677	        String lastName = normalizeHouseholdField(owner.getLastName());
678	        return (int) this.clinicService.findAllOwners().stream()
679	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
680	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
681	            .count();
682	    }
683	
684	    /**
685	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
686	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
687	     * unusually high daily signup volume.
688	     */
689	    private boolean isBulkSignupWarning() {
690	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
691	    }
692	
693	    /** The number of existing owners whose registration date is {@code date}. */
694	    private int countOwnersRegisteredOn(LocalDate date) {
695	        return (int) this.clinicService.findAllOwners().stream()
696	            .filter(existing -> date.equals(existing.getRegistrationDate()))
697	            .count();
698	    }
699	
700	    /**
701	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
702	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
703	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
704	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
705	     * the telephone is part of the key, two owners with the same last name and postcode but
706	     * different telephones resolve to different keys and are both allowed (the later one becoming a
707	     * possible duplicate rather than a hard conflict).
708	     */
709	    private static String identityKey(Owner owner) {
710	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
711	        String email = owner.getEmail() == null ? "" : owner.getEmail();
712	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
713	        return Owner.sha256HexLower(key);
714	    }
715	
716	    /**
717	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
718	     * the sole duplicate condition: the previously separate telephone, email and household checks -
719	     * including the household-duplicate check derived from the {@code householdId} - are now all
720	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
721	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
722	     */
723	    private boolean isDuplicate(Owner owner) {
724	        String key = owner.getIdentityKey();
725	        return this.clinicService.findAllOwners().stream()
726	            .filter(existing -> !existing.isDeleted())
727	            .map(Owner::getIdentityKey)
728	            .filter(existing -> existing != null)
729	            .anyMatch(key::equals);
730	    }
731	
732	    /** Common street-type abbreviations expanded during address normalization. */
733	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
734	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
735	
736	    /**
737	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
738	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
739	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
740	     * string when {@code address} is null or blank after normalization.
741	     */
742	    private static String normalizeAddress(String address) {
743	        if (address == null) {
744	            return "";
745	        }
746	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
747	        if (collapsed.isEmpty()) {
748	            return "";
749	        }
750	        StringBuilder sb = new StringBuilder(collapsed.length());
751	        for (String token : collapsed.split(" ")) {
752	            if (sb.length() > 0) {
753	                sb.append(' ');
754	            }
755	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
756	        }
757	        return sb.toString();
758	    }
759	
760	    /**
761	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
762	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
763	     */
764	    private static String normalizeHouseholdField(String value) {
765	        if (value == null) {
766	            return "";
767	        }
768	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
769	    }
770	
771	    /**
772	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
773	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
774	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
775	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
776	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
777	     * identity key and the possible-duplicate soft match compare on.
778	     */
779	    private static String soundex(String value) {
780	        if (value == null) {
781	            return "";
782	        }
783	        StringBuilder letters = new StringBuilder();
784	        for (char c : value.toCharArray()) {
785	            if (c < 128 && Character.isLetter(c)) {
786	                letters.append(Character.toUpperCase(c));
787	            }
788	        }
789	        if (letters.length() == 0) {
790	            return "";
791	        }
792	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
793	        char previous = soundexDigit(letters.charAt(0));
794	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
795	            char c = letters.charAt(i);
796	            if (c == 'H' || c == 'W') {
797	                continue;
798	            }
799	            char digit = soundexDigit(c);
800	            if (digit != '0' && digit != previous) {
801	                code.append(digit);
802	            }
803	            previous = digit;
804	        }
805	        while (code.length() < 4) {
806	            code.append('0');
807	        }
808	        return code.toString();
809	    }
810	
811	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
812	    private static char soundexDigit(char c) {
813	        switch (c) {
814	            case 'B': case 'F': case 'P': case 'V':
815	                return '1';
816	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
817	                return '2';
818	            case 'D': case 'T':
819	                return '3';
820	            case 'L':
821	                return '4';
822	            case 'M': case 'N':
823	                return '5';
824	            case 'R':
825	                return '6';
826	            default:
827	                return '0';
828	        }
829	    }
830	
831	    /**
832	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
833	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
834	     * key rather than re-derived from the underlying fields here, so the household is described in one
835	     * place and every household-keyed value stays consistent with it.
836	     */
837	    private List<Owner> findHousemates(Owner owner) {
838	        String householdId = householdId(owner);
839	        return this.clinicService.findAllOwners().stream()
840	            .filter(existing -> !existing.isDeleted())
841	            .filter(existing -> householdId(existing).equals(householdId))
842	            .toList();
843	    }
844	
845	    /**
846	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
847	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
848	     */
849	    private int countHouseholdMembers(Owner owner) {
850	        return findHousemates(owner).size() + 1;
851	    }
852	
853	    /**
854	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
855	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
856	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
857	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
858	     * applies - when the owner has no existing household member.
859	     */
860	    private Integer membershipLevelCapForHousehold(Owner owner) {
861	        OptionalInt maxLevel = findHousemates(owner).stream()
862	            .mapToInt(Owner::getMembershipLevel)
863	            .max();
864	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
865	    }
866	
867	    /**
868	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
869	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
870	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
871	     * string standing in for a missing postcode), so housemates always resolve to the same value
872	     * regardless of registration order, and owners sharing a last name and postcode share it
873	     * automatically.
874	     */
875	    private static String householdId(Owner owner) {
876	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
877	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
878	        return Owner.sha256Hex(key).substring(0, 12);
879	    }
880	}
